(() => {
  const apply = () => {
    const card = document.querySelector('[data-name="ugreen nexode cargador usb c 100w 4 puertos gan"]');
    if (!card) return;
    const link = card.querySelector('.offer-button');
    if (link) link.href = 'https://amzn.to/4xROXgd';
    const art = card.querySelector('.product-art');
    if (art) {
      art.style.cssText = 'display:flex;align-items:center;justify-content:center;padding:0;background:#fff;overflow:hidden;';
      art.innerHTML = '<img src="data:image/jpeg;base64," alt="UGREEN Nexode Cargador USB-C 100W" loading="lazy" style="width:auto;height:auto;max-width:78%;max-height:78%;object-fit:contain;display:block;margin:auto">';
      art.removeAttribute('aria-hidden');
      art.setAttribute('role','img');
      art.setAttribute('aria-label','UGREEN Nexode Cargador USB-C 100W');
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply);
  else apply();
})();
